<script lang="ts">
 import type {AppState,Command,EvidenceArtifact} from '../lib/types';
 import {computeScore} from '../lib/scoring';
 import {dossierUrl} from '../lib/navigation';
 import {safeUrl} from '../lib/domain';
 import {newCommandId,uploadFile,withCommandId,stageFileForCommand,unstageFileForCommand,getSessionGeneration,SessionSupersededError} from '../lib/repository';
 import ComplexForm from './ComplexForm.svelte';
 import {supabase} from '../lib/supabase';
 import {extractPdf,type PdfExtraction} from '../lib/workspace-api';
 import GeometryImport from './GeometryImport.svelte';
 import {sourceOriginLabel,sourceAvailabilityLabel} from '../lib/presentation';
 let {workspace,commit}:{workspace:AppState;commit:(c:Command)=>Promise<void>}=$props();
 let category=$state('complexes');let search=$state('');let page=$state(0);let creating=$state(false);let importing=$state(false);let importingGeometry=$state(false);
 let documentKind=$state<EvidenceArtifact['kind']>('document');let complexId=$state('');let phaseId=$state('');let source=$state('');let text=$state('');let date=$state('');let url=$state('');let files=$state<FileList>();let busy=$state(false);let error=$state('');let notice=$state('');
 const matches=(s:string)=>s.toLowerCase().includes(search.toLowerCase());
 const complexes=$derived(workspace.complexes.filter(z=>matches(`${z.name} ${z.address} ${z.developer} ${z.bin ?? ''}`)));
 const organizations=$derived([...new Map(workspace.complexes.filter(z=>!!z.developer).map(z=>[z.bin || z.developer,{id:z.bin || z.developer,name:z.developer,bin:z.bin,complexes:workspace.complexes.filter(other=>z.bin ? other.bin===z.bin : other.developer===z.developer)}])).values()].filter(o=>matches(`${o.name} ${o.bin ?? ''}`)));
 const documents=$derived((workspace.artifacts ?? []).filter(a=>a.kind!=='publication'&&matches(`${a.id} ${a.source} ${a.text} ${a.date ?? ''} ${a.complexId}`)));
 $effect(()=>{search;category;page=0;});$effect(()=>{complexId;phaseId='';});
 let importIntent:{key:string;session:number;id:string;commandId:string;artifactCommandId:string;mediaId:string;media?:Awaited<ReturnType<typeof uploadFile>>;mediaDone:boolean;mediaCommand?:Command;artifactCommand?:Command}|undefined;
 let extraction=$state<PdfExtraction|null>(null);let extractionPage=$state(1);
 async function parsePdf(){busy=true;error='';extraction=null;try{const file=files?.[0];if(!file)throw new Error('Выберите оригинал PDF');extraction=await extractPdf(file);extractionPage=1;text=extraction.pages[0]?.text??'';}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function saveDocument(){if(busy)return;busy=true;error='';const session=getSessionGeneration();
 const key=JSON.stringify([complexId,phaseId,documentKind,source,text,date,url,files?.[0]?.name,files?.[0]?.size,files?.[0]?.lastModified]);
 try{if(!complexId||!source.trim()||!text.trim())throw new Error('Укажите ЖК, источник и содержание документа.');
 if(importIntent&&importIntent.key!==key)throw new Error('Для повтора сохранения верните исходные поля. Результат прежнего запроса ещё не подтверждён.');
 importIntent??={key,session,id:`DOC-${newCommandId()}`,commandId:newCommandId(),artifactCommandId:newCommandId(),mediaId:newCommandId(),mediaDone:false};const pending=importIntent;
 const checkSession=()=>{if(session!==getSessionGeneration()||pending.session!==session)throw new SessionSupersededError();};checkSession();
 if(files?.[0]&&!pending.media){pending.media=await uploadFile(files[0],complexId,{mediaId:pending.mediaId});stageFileForCommand(pending.commandId,pending.media.path);checkSession();pending.mediaCommand={type:'media',media:{...pending.media,date:date||pending.media.date,note:source}};}
 if(pending.media&&!pending.mediaDone){await commit(withCommandId(pending.mediaCommand!,pending.commandId));pending.mediaDone=true;unstageFileForCommand(pending.commandId);checkSession();}
 pending.artifactCommand??={type:'artifact.register',artifact:{id:pending.id,complexId,...(phaseId?{phaseId}:{}),kind:documentKind,origin:'import',source,text,...(extraction?{pageNumber:extractionPage}:{}),...(date?{date}:{}),...(url?{url}:{}),...(pending.media?{mediaId:pending.media.id}:{})}};
 await commit(withCommandId(pending.artifactCommand,pending.artifactCommandId));checkSession();notice='Документ сохранён. Применимость проверяется в досье.';importIntent=undefined;importing=false;source='';text='';files=undefined;extraction=null;
 }catch(e){if(session===getSessionGeneration())error=e instanceof Error?e.message:String(e);}finally{busy=false;}}
</script>
<div class="page-heading"><div><p class="eyebrow">ВНУТРЕННИЙ КАТАЛОГ</p><h1>Реестры</h1></div><div class="actions"><button onclick={()=>importingGeometry=!importingGeometry}>Импорт GeoJSON</button><button onclick={()=>creating=!creating}>Добавить ЖК</button><button class="primary" onclick={()=>importing=!importing}>Добавить документ</button></div></div>
{#if importingGeometry}<GeometryImport {workspace} {commit}/>{/if}
{#if creating}<ComplexForm onsave={async complex=>{await commit({type:'complex',complex});creating=false;}} oncancel={()=>creating=false}/>{/if}
{#if notice}<p class="notice mb-4" role="status">{notice}</p>{/if}{#if error}<p class="error mb-4" role="alert">{error}</p>{/if}
{#if importing}<form class="panel space-y-4 mb-5" onsubmit={e=>{e.preventDefault();void saveDocument();}}><h2>Ручной импорт документа</h2><label>Тип материала<select bind:value={documentKind}><option value="document">Документ</option><option value="legal-review">Правовая сверка</option><option value="observation">Инженерное наблюдение</option><option value="event">Датированное событие</option></select></label><div class="form-grid"><label>ЖК<select required bind:value={complexId}><option value="">Выберите ЖК</option>{#each workspace.complexes as z}<option value={z.id}>{z.name}</option>{/each}</select></label><label>Очередь<select bind:value={phaseId}><option value="">Весь ЖК / не определена</option>{#each (workspace.phases??[]).filter(p=>p.complexId===complexId) as p}<option value={p.id}>{p.name}</option>{/each}</select></label><label>Источник / номер документа<input required bind:value={source}/></label><label>Дата документа, если известна<input type="date" bind:value={date}/></label></div><label>URL оригинала<input type="url" bind:value={url}/></label><label>Исходное содержание / текст выбранной страницы<textarea required rows="6" bind:value={text}></textarea></label><label>Оригинал PDF / изображение<input type="file" accept="application/pdf,image/png,image/jpeg,image/webp" bind:files/></label>{#if supabase}<button type="button" disabled={busy||files?.[0]?.type!=='application/pdf'} onclick={parsePdf}>Извлечь текст PDF</button>{/if}{#if extraction}<label>Страница оригинала<select bind:value={extractionPage} onchange={()=>text=extraction?.pages.find(p=>p.page===extractionPage)?.text??''}>{#each extraction.pages as p}<option value={p.page}>Страница {p.page}</option>{/each}</select></label><p class="notice">{extraction.limitations.join(' · ')}</p>{/if}<p class="muted">Происхождение: ручной импорт. Текст и применимость требуют проверки; загрузка не подтверждает факт.</p><button disabled={busy} class="primary">{busy?'Сохранение…':'Сохранить документ'}</button></form>{/if}
<div class="actions mb-5" aria-label="Категории реестров">{#each [{id:'complexes',label:'ЖК'},{id:'organizations',label:'Организации'},{id:'documents',label:'Документы и источники'}] as c}<button aria-pressed={category===c.id} onclick={()=>category=c.id}>{c.label}</button>{/each}</div><label class="mb-5">Поиск по каталогу<input type="search" bind:value={search} placeholder="Название, адрес, БИН, номер документа"/></label>
{#if category==='complexes'}<div class="table-scroll panel"><table><thead><tr><th>ЖК / очередь</th><th>Застройщик / БИН</th><th>Правовое основание</th><th>Риск</th></tr></thead><tbody>{#each complexes.slice(page*25,(page+1)*25) as z}{@const s=computeScore(z.factors)}<tr><td><a href={dossierUrl(z.id)}><b>{z.name}</b></a><small>{z.address} · {z.stage || 'Стадия неизвестна'}</small>{#each (workspace.phases??[]).filter(p=>p.complexId===z.id) as p}<small><a href={dossierUrl(z.id,p.id)}>{p.name} ↗</a></small>{/each}<small>{z.demo?'DEMO':z.origin} · {workspace.ads.filter(a=>a.zkId===z.id).length} публикаций</small></td><td>{z.developer}<small>{z.bin||'БИН неизвестен'}</small></td><td>{z.legalBasis.status==='verified'?'Основание проверено':z.legalBasis.status==='absent-verified'?'Отсутствие проверено':'Не установлено'}<small>{z.legalBasis.checkedAt||'Дата неизвестна'}</small></td><td><span class="registry-risk" role="img" aria-label={`Риск: ${s.score} баллов`} title={`${s.score} баллов`}><span class="registry-risk-dot {s.zone}" aria-hidden="true"></span><span aria-hidden="true">{s.score}</span></span></td></tr>{:else}<tr><td colspan="4">ЖК не найдены.</td></tr>{/each}</tbody></table></div>
{:else if category==='organizations'}<div class="space-y-4">{#each organizations.slice(page*25,(page+1)*25) as o}<article class="panel"><h3>{o.name}</h3><p>БИН: {o.bin||'неизвестен'} · роль из карточек: застройщик</p><p class="muted">Роль требует документального подтверждения. Совпадение названия не доказывает идентичность.</p><div class="actions mt-4">{#each o.complexes as z}<a class="button small" href={dossierUrl(z.id,undefined,'relations')}>{z.name} ↗</a>{/each}</div></article>{:else}<p>Организации не найдены.</p>{/each}</div>
{:else}<div class="space-y-4">{#each documents.slice(page*25,(page+1)*25) as a}<article class="panel"><h3>{a.source}</h3><p>{a.date||'Дата неизвестна'} · фиксация: {a.capturedAt}</p><p class="my-3">{a.text.slice(0,250)}</p><span class="badge">{sourceOriginLabel(a.origin)} · {sourceAvailabilityLabel(a.availability)} · применимость не проверена</span><div class="actions mt-4"><a class="button small" href={dossierUrl(a.complexId,a.phaseId,'verification',a.id)}>Открыть в досье</a>{#if safeUrl(a.url)}<a class="button small" href={safeUrl(a.url)} target="_blank" rel="noopener noreferrer">Источник ↗</a>{/if}</div></article>{:else}<section class="panel"><h2>Документов пока нет</h2><p>Добавьте ручной материал или оригинал PDF.</p></section>{/each}</div>{/if}
<div class="actions mt-5"><button disabled={page===0} onclick={()=>page--}>Назад</button><span>Страница {page+1}</span><button disabled={(page+1)*25>=(category==='complexes'?complexes.length:category==='organizations'?organizations.length:documents.length)} onclick={()=>page++}>Далее</button></div>
<details class="panel mt-6"><summary>Внешние реестры</summary><p class="muted mt-3">Автоматические адаптеры не подключены. Отказ внешнего сайта не означает отсутствие правового основания.</p></details>
